public sealed class Overdue : Specification<Invoice> {
    private readonly int _days;
    public Overdue(int days) => _days = days;
    protected override Expression<Func<Invoice, bool>> ToExpression()
        => i => i.DueDate < DateTime.UtcNow.AddDays(-_days);
}

var rule = new Overdue(30).And(new InCollection().Not());
var rows = await db.Invoices.Where(rule.ToExpression()).ToListAsync();

static Func<Invoice, bool> Overdue(int days) => i => i.DueDate < DateTime.UtcNow.AddDays(-days);
static Func<Invoice, bool> And(params Func<Invoice, bool>[] rules) => i => rules.All(r => r(i));

var collectable = And(Overdue(30), i => i.NoticesSent >= 3, i => !i.InCollection);
var toCollect = invoices.Where(collectable);

